/**
 * Motion40 — "SAUDI ARABIA · DIGITAL INFRASTRUCTURE GRID"
 * 1920x1080 · 60 fps · 1440 frames (24 s) · PERFECT LOOP
 *
 * Peta TIDAK langsung jadi: terbentuk memancar dari Riyadh, lalu kamera
 * bergerak menerus (yaw + pitch + dolly, satu siklus penuh per loop → seam
 * nol). Teks sengaja minim supaya pembeli bisa menimpa teksnya sendiri.
 *
 * Geometri: Natural Earth (DOMAIN PUBLIK) via nvkelso/natural-earth-vector.
 *   - garis negara  : ne_10m_admin_0_countries (daratan + Kep. Farasan)
 *   - batas provinsi: ne_10m_admin_1_states_provinces (13 mintaqah)
 *   - kota          : ne_10m_populated_places_simple
 *
 * PROYEKSI: Albers Equal Area Conic, paralel standar 19 dan 29 LU, meridian
 * tengah 45 BT, acuan 24 LU. EQUAL-AREA dipilih dengan sengaja, bukan sekadar
 * mengikuti versi Amerika dan Brasil: cerita peta ini justru soal perbandingan
 * LUAS. Ash Sharqiyah sendirian hampir sepertiga negara dan Rub' al Khali
 * mendominasi selatan; proyeksi konformal akan membesarkan provinsi utara
 * terhadap selatan dan merusak perbandingan itu. Diuji: 1 derajat bujur
 * terukur 101,2 km di 24 LU (benar 101,8) dan 1 derajat lintang 111,6 km
 * (benar 110,9 — equal-area memang menukar ketepatan jarak demi luas).
 *
 * TANPA PELEBURAN, TANPA SISIPAN. Berbeda dari versi Prancis, Spanyol, dan
 * Britania, Natural Earth memberi Arab Saudi tepat 13 mintaqah — sudah pada
 * tingkat yang benar untuk digambar, jadi tidak perlu pembatalan sisi sama
 * sekali. Tidak ada pula wilayah terpencil yang perlu disisipkan; Kepulauan
 * Farasan cukup dekat untuk dibiarkan di tempatnya.
 *
 * FRAMING: sudut barat laut Arab Saudi (wilayah Tabuk) adalah DARATAN, bukan
 * laut, jadi peta harus digeser ke kanan agar tidak menabrak blok judul.
 * Menggesernya sejauh mungkin memberi peta 14% lebih besar tapi menyisakan
 * ruang 570 px di kiri lawan 166 px di kanan — jelas berat sebelah. Dipilih
 * kompromi: MAPK 1,04 dengan geseran 40 px, sisa ruang 470/388 px, diuji di
 * 72 pose kamera tanpa satu titik pun menyentuh blok judul.
 *
 * Batas iterasi grid titik DIHITUNG dari bbox, bukan angka tetap.
 */
import React, {
  useEffect,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
} from 'react';
import {
  AbsoluteFill,
  continueRender,
  delayRender,
  random,
  useCurrentFrame,
  useVideoConfig,
} from 'remotion';
import {noise3D} from '@remotion/noise';

/* ═══════════════════════════════════════════════════════════ FONT */

const FONT_CSS = `
@font-face{font-family:'MxMono40';src:url(data:font/woff2;base64,) format('woff2');font-weight:400;font-style:normal;font-display:block;}
@font-face{font-family:'MxTitle40';src:url(data:font/woff2;base64,) format('woff2');font-weight:700;font-style:normal;font-display:block;}
`;

let fontsPromise: Promise<unknown> | null = null;
const ensureFonts = () => {
  if (fontsPromise) return fontsPromise;
  const st = document.createElement('style');
  st.textContent = FONT_CSS;
  document.head.appendChild(st);
  fontsPromise = Promise.all([
    (document as any).fonts.load("400 24px 'MxMono40'"),
    (document as any).fonts.load("700 24px 'MxTitle40'"),
  ]).catch(() => null);
  return fontsPromise;
};

const useEmbeddedFonts = () => {
  const [handle] = useState(() => delayRender('fonts-motion40'));
  const [ready, setReady] = useState(false);
  useEffect(() => {
    let done = false;
    const finish = () => {
      if (done) return;
      done = true;
      setReady(true);
      continueRender(handle);
    };
    const to = setTimeout(finish, 2500);
    ensureFonts().then(finish, finish);
    return () => clearTimeout(to);
  }, [handle]);
  return ready;
};

